package nativegen

import (
	"bytes"
	"fmt"
	"go/format"
	"sort"
	"strconv"
	"strings"
)

// header starts every generated file: Go's convention for generated
// code, and the declarations' hash (stale when it differs).
func header(comment, hash string) string {
	return fmt.Sprintf("%s Code generated by asuka native. DO NOT EDIT.\n%s asuka:native %s\n", comment, comment, hash)
}

// HashOf is the declarations' hash a generated file records ("" for
// none).
func HashOf(src []byte) string {
	for _, line := range strings.SplitN(string(src), "\n", 4) {
		if i := strings.Index(line, "asuka:native "); i >= 0 {
			return strings.TrimSpace(line[i+len("asuka:native "):])
		}
	}
	return ""
}

var methodOf = map[Kind]string{
	Bool: "Bool", Int8: "Int8", Int16: "Int16", Int32: "Int32", Int64: "Int64", Int: "Int",
	Uint8: "Uint8", Uint16: "Uint16", Uint32: "Uint32", Uint64: "Uint64", Uint: "Uint",
	Float32: "Float32", Float64: "Float64", String: "String", Bytes: "Data", Time: "Time", Duration: "Duration",
}

var goBasic = map[Kind]string{
	Int8: "int8", Int16: "int16", Int32: "int32", Int64: "int64", Int: "int",
	Uint8: "uint8", Uint16: "uint16", Uint32: "uint32", Uint64: "uint64", Uint: "uint", String: "string",
}

// mangle names a type in helper functions' names.
func mangle(t *Type) string {
	switch t.Kind {
	case Slice:
		return "Slice" + mangle(t.Elem)
	case Map:
		return "Map" + mangle(t.Elem)
	case Optional:
		return "Opt" + mangle(t.Elem)
	case Struct, Enum, Object:
		return t.Name
	}
	return methodOf[t.Kind]
}

// composite reports whether t's encoding is a helper function.
func composite(t *Type) bool {
	switch t.Kind {
	case Slice, Map, Optional, Struct, Object:
		return true
	}
	return false
}

type goGen struct {
	p       *Package
	b       bytes.Buffer
	helpers map[string]*Type
	enums   map[string]*EnumDecl
}

func (g *goGen) printf(format string, args ...any) { fmt.Fprintf(&g.b, format, args...) }

// enc writes v of type t with writer w.
func (g *goGen) enc(t *Type, w, v string) string {
	switch {
	case t.Kind == Enum:
		e := g.enums[t.Name]
		return fmt.Sprintf("%s.%s(%s(%s))", w, methodOf[e.Basic], goBasic[e.Basic], v)
	case composite(t):
		g.need(t)
		return fmt.Sprintf("nativeWrite%s(%s, %s)", mangle(t), w, v)
	}
	return fmt.Sprintf("%s.%s(%s)", w, methodOf[t.Kind], v)
}

// dec reads a value of type t with reader r.
func (g *goGen) dec(t *Type, r string) string {
	switch {
	case t.Kind == Enum:
		e := g.enums[t.Name]
		return fmt.Sprintf("%s(%s.%s())", t.Name, r, methodOf[e.Basic])
	case composite(t):
		g.need(t)
		return fmt.Sprintf("nativeRead%s(%s)", mangle(t), r)
	}
	return fmt.Sprintf("%s.%s()", r, methodOf[t.Kind])
}

// need records a composite type's helpers (and its parts').
func (g *goGen) need(t *Type) {
	if _, ok := g.helpers[mangle(t)]; ok {
		return
	}
	g.helpers[mangle(t)] = t
	if t.Elem != nil && composite(t.Elem) {
		g.need(t.Elem)
	}
}

// zero is t's zero value as Go writes it.
func zero(t *Type) string {
	switch t.Kind {
	case Bool:
		return "false"
	case String:
		return `""`
	case Bytes, Slice, Map, Optional, Object, Func:
		return "nil"
	case Struct, Time:
		return t.Go + "{}"
	}
	return t.Go + "(0)"
}

// GenerateGo writes the package's Go: its _native.go.
func GenerateGo(p *Package) ([]byte, error) {
	g := &goGen{p: p, helpers: map[string]*Type{}, enums: map[string]*EnumDecl{}}
	for _, e := range p.Enums {
		g.enums[e.Name] = e
	}
	var body bytes.Buffer
	main := g.b
	_ = main

	// The module.
	var errs []string
	for _, e := range p.Errors {
		errs = append(errs, e.Name)
	}
	g.printf("// nativeModule is the package's native code, as the hosts find it.\n")
	g.printf("var nativeModule = &native.Module{ID: %q, Swift: %q, Kotlin: %q, Errors: []error{%s}}\n\n",
		p.Path, SwiftClass(p.Path), KotlinClass(p.Path), strings.Join(errs, ", "))
	for _, it := range p.Interfaces {
		g.iface(it)
	}
	for _, v := range p.Views {
		g.view(v)
	}
	body.Write(g.b.Bytes())
	g.b.Reset()

	// The helpers, in a stable order (each may add more).
	done := map[string]bool{}
	for {
		var names []string
		for n := range g.helpers {
			if !done[n] {
				names = append(names, n)
			}
		}
		if len(names) == 0 {
			break
		}
		sort.Strings(names)
		for _, n := range names {
			done[n] = true
			g.helper(g.helpers[n])
		}
	}
	body.Write(g.b.Bytes())

	var out bytes.Buffer
	out.WriteString(header("//", p.Hash))
	fmt.Fprintf(&out, "\npackage %s\n\nimport (\n", p.Name)
	for _, imp := range g.imports(body.String()) {
		fmt.Fprintf(&out, "\t%q\n", imp)
	}
	out.WriteString(")\n\n")
	out.Write(body.Bytes())
	src, err := format.Source(out.Bytes())
	if err != nil {
		return out.Bytes(), fmt.Errorf("nativegen: the generated Go doesn't parse: %v", err)
	}
	return src, nil
}

func (g *goGen) imports(body string) []string {
	var imps []string
	for _, c := range []struct{ prefix, path string }{
		{"context.", "context"}, {"time.", "time"},
		{"native.", "github.com/egoist/asuka/native"}, {"signal.", "github.com/egoist/asuka/signal"}, {"ui.", "github.com/egoist/asuka/ui"},
	} {
		if strings.Contains(body, c.prefix) {
			imps = append(imps, c.path)
		}
	}
	return imps
}

func (g *goGen) iface(it *Interface) {
	n := it.Name
	g.printf("// New%s makes the platform's %s: Go's, where the package implements it\n", n, n)
	g.printf("// in Go (implement%s), else its native code's (Swift on iOS and macOS,\n", n)
	g.printf("// Kotlin on Android, JavaScript on the web). Without one, it returns an\n")
	g.printf("// error that is errors.ErrUnsupported.\n")
	g.printf("func New%s() (%s, error) {\n", n, n)
	g.printf("\tif nativeImpl%s != nil {\n\t\treturn nativeImpl%s()\n\t}\n", n, n)
	g.printf("\to, err := nativeModule.New(%d, %q)\n\tif err != nil {\n\t\treturn nil, err\n\t}\n", it.Index, n)
	g.printf("\treturn &native%s{o}, nil\n}\n\n", n)
	g.printf("var nativeImpl%s func() (%s, error)\n\n", n, n)
	g.printf("// implement%s makes New%s return Go's implementation: call it from an\n", n, n)
	g.printf("// init function of a file built for the platforms where the package's\n")
	g.printf("// native code is Go (Windows, Linux).\n")
	g.printf("func implement%s(make func() (%s, error)) { nativeImpl%s = make }\n\n", n, n, n)
	g.printf("// native%s is a %s on the platform's side.\n", n, n)
	g.printf("type native%s struct{ o *native.Object }\n\n", n)
	for _, m := range it.Methods {
		g.method(it, m)
	}
}

func (g *goGen) method(it *Interface, m *Method) {
	var params []string
	if m.Context {
		params = append(params, "ctx context.Context")
	}
	for _, p := range m.Params {
		params = append(params, p.Name+" "+p.Type.Go)
	}
	var results []string
	if m.Result != nil {
		results = append(results, m.Result.Go)
	}
	if m.Error {
		results = append(results, "error")
	}
	res := strings.Join(results, ", ")
	if len(results) > 1 {
		res = "(" + res + ")"
	}
	g.printf("func (x *native%s) %s(%s) %s {\n", it.Name, m.Name, strings.Join(params, ", "), res)
	// What a failure returns: with no error result, it panics (a method
	// that can't fail failing is a bug).
	fail := func(err string) string {
		switch {
		case m.Error && m.Result != nil:
			return fmt.Sprintf("return %s, %s", zero(m.Result), err)
		case m.Error:
			return "return " + err
		}
		return "panic(" + err + ")"
	}
	g.printf("\tw := native.NewWriter()\n")
	for i, p := range m.Params {
		if p.Type.Kind == Func {
			g.callback(fmt.Sprintf("cb%d", i), p.Name, p.Type.Func)
			g.printf("\tw.Func(cb%d)\n", i)
			continue
		}
		g.printf("\t%s\n", g.enc(p.Type, "w", p.Name))
	}
	call := fmt.Sprintf("x.o.Call(%d, w)", m.Index)
	if m.Context {
		call = fmt.Sprintf("x.o.CallContext(ctx, %d, w)", m.Index)
	}
	g.printf("\tr, err := %s\n", call)
	if m.Close {
		g.printf("\tx.o.Release()\n")
	}
	g.printf("\tif err != nil {\n\t\t%s\n\t}\n", fail("err"))
	switch {
	case m.Result != nil && m.Error:
		g.printf("\tv := %s\n\tif err := r.Done(); err != nil {\n\t\treturn %s, err\n\t}\n\treturn v, nil\n", g.dec(m.Result, "r"), zero(m.Result))
	case m.Result != nil:
		g.printf("\tv := %s\n\tif err := r.Done(); err != nil {\n\t\tpanic(err)\n\t}\n\treturn v\n", g.dec(m.Result, "r"))
	case m.Error:
		g.printf("\treturn r.Done()\n")
	default:
		g.printf("\tif err := r.Done(); err != nil {\n\t\tpanic(err)\n\t}\n")
	}
	g.printf("}\n\n")
}

// callback registers a func parameter, released when the call returns.
func (g *goGen) callback(v, f string, ft *FuncType) {
	g.printf("\tvar %s *native.Callback\n\tif %s != nil {\n", v, f)
	g.printf("\t\t%s = native.NewCallback(func(cr *native.Reader, cw *native.Writer) {\n", v)
	var args []string
	for i, p := range ft.Params {
		g.printf("\t\t\ta%d := %s\n", i, g.dec(p.Type, "cr"))
		args = append(args, "a"+strconv.Itoa(i))
	}
	g.printf("\t\t\tif cr.Err() != nil {\n\t\t\t\treturn\n\t\t\t}\n")
	if ft.Result != nil {
		g.printf("\t\t\t%s\n", g.enc(ft.Result, "cw", f+"("+strings.Join(args, ", ")+")"))
	} else {
		g.printf("\t\t\t%s(%s)\n", f, strings.Join(args, ", "))
	}
	g.printf("\t\t}, %v)\n\t\tdefer %s.Release()\n\t}\n", ft.Result == nil, v)
}

func (g *goGen) helper(t *Type) {
	n := mangle(t)
	switch t.Kind {
	case Struct:
		var st *StructDecl
		for _, s := range g.p.Structs {
			if s.Name == t.Name {
				st = s
			}
		}
		g.printf("func nativeWrite%s(w *native.Writer, v %s) {\n", n, t.Name)
		for _, f := range st.Fields {
			g.printf("\t%s\n", g.enc(f.Type, "w", "v."+f.Name))
		}
		g.printf("}\n\nfunc nativeRead%s(r *native.Reader) (v %s) {\n", n, t.Name)
		for _, f := range st.Fields {
			g.printf("\tv.%s = %s\n", f.Name, g.dec(f.Type, "r"))
		}
		g.printf("\treturn v\n}\n\n")
	case Slice:
		g.printf("func nativeWrite%s(w *native.Writer, v %s) {\n\tw.Len(len(v))\n\tfor _, e := range v {\n\t\t%s\n\t}\n}\n\n", n, t.Go, g.enc(t.Elem, "w", "e"))
		g.printf("func nativeRead%s(r *native.Reader) %s {\n\tn := r.Len()\n\tif n == 0 {\n\t\treturn nil\n\t}\n", n, t.Go)
		g.printf("\tv := make(%s, n)\n\tfor i := range v {\n\t\tv[i] = %s\n\t}\n\treturn v\n}\n\n", t.Go, g.dec(t.Elem, "r"))
	case Map:
		g.printf("func nativeWrite%s(w *native.Writer, v %s) {\n\tw.Len(len(v))\n\tfor k, e := range v {\n\t\tw.String(k)\n\t\t%s\n\t}\n}\n\n", n, t.Go, g.enc(t.Elem, "w", "e"))
		g.printf("func nativeRead%s(r *native.Reader) %s {\n\tn := r.Len()\n\tif n == 0 {\n\t\treturn nil\n\t}\n", n, t.Go)
		g.printf("\tv := make(%s, n)\n\tfor i := 0; i < n && r.Err() == nil; i++ {\n\t\tk := r.String()\n\t\tv[k] = %s\n\t}\n\treturn v\n}\n\n", t.Go, g.dec(t.Elem, "r"))
	case Optional:
		g.printf("func nativeWrite%s(w *native.Writer, v %s) {\n\tw.Present(v != nil)\n\tif v != nil {\n\t\t%s\n\t}\n}\n\n", n, t.Go, g.enc(t.Elem, "w", "*v"))
		g.printf("func nativeRead%s(r *native.Reader) %s {\n\tif !r.Present() {\n\t\treturn nil\n\t}\n\tv := %s\n\treturn &v\n}\n\n", n, t.Go, g.dec(t.Elem, "r"))
	case Object:
		g.printf("func nativeWrite%s(w *native.Writer, v %s) {\n\tn, _ := v.(*native%s)\n\tif n == nil {\n\t\tw.Object(nil)\n\t\treturn\n\t}\n\tw.Object(n.o)\n}\n\n", n, t.Name, t.Name)
		g.printf("func nativeRead%s(r *native.Reader) %s {\n\to := nativeModule.Object(r)\n\tif o == nil {\n\t\treturn nil\n\t}\n\treturn &native%s{o}\n}\n\n", n, t.Name, t.Name)
	}
}

func (g *goGen) view(v *View) {
	n := v.Name
	doc := v.Doc
	if doc == "" {
		doc = fmt.Sprintf("%s shows the platform's %s view.", n, n)
	}
	for _, l := range strings.Split(doc, "\n") {
		g.printf("// %s\n", l)
	}
	if !strings.HasPrefix(doc, n+" ") {
		g.printf("//\n// %s shows the platform's %s view.\n", n, n)
	}
	g.printf("func %s(p %sProps) ui.Node {\n\tprops := make(map[string]any, %d)\n", n, n, len(v.Props))
	for _, f := range v.Props {
		if f.Accessor {
			g.printf("\tif a := p.%s; a != nil {\n\t\tprops[%q] = signal.Func(func() []byte {\n\t\t\tw := native.NewWriter()\n\t\t\t%s\n\t\t\treturn w.Take()\n\t\t})\n\t}\n",
				f.Name, f.Name, g.enc(f.Type, "w", "a.Get()"))
		} else {
			g.printf("\t{\n\t\tw := native.NewWriter()\n\t\t%s\n\t\tprops[%q] = w.Take()\n\t}\n", g.enc(f.Type, "w", "p."+f.Name), f.Name)
		}
	}
	g.printf("\ton := make(map[string]func(ui.NativeEvent), %d)\n", len(v.Events))
	for _, e := range v.Events {
		g.printf("\tif f := p.%s; f != nil {\n\t\ton[%q] = func(ev ui.NativeEvent) {\n\t\t\tr := native.NewReader(ev.Bytes(\"v\"))\n", e.Name, e.Name)
		var args []string
		for i, a := range e.Type.Func.Params {
			g.printf("\t\t\ta%d := %s\n", i, g.dec(a.Type, "r"))
			args = append(args, "a"+strconv.Itoa(i))
		}
		g.printf("\t\t\tif r.Err() == nil {\n\t\t\t\tf(%s)\n\t\t\t}\n\t\t}\n\t}\n", strings.Join(args, ", "))
	}
	style := ""
	if v.Style {
		style = ", Style: p.Style"
	}
	g.printf("\treturn ui.Native(native.ViewKind(nativeModule, %q), ui.NativeProps{Props: props, On: on%s})\n}\n\n", n, style)

	// Go's implementation (Windows, Linux).
	g.printf("// %sNative is a %s where the package's native code is Go (Windows,\n// Linux): the platform's view (native.View's Handle) and its props.\n", n, n)
	g.printf("type %sNative interface {\n\tHandle() uintptr\n", n)
	for _, f := range v.Props {
		g.printf("\tSet%s(%s %s)\n", f.Name, lowerCamel(f.Name), f.Type.Go)
	}
	g.printf("}\n\n")
	g.printf("// %sEvents sends a %s's events (Go's implementation), and has its\n// context: the host's view it goes in.\n", n, n)
	g.printf("type %sEvents struct{ Context native.Context }\n\n", n)
	for _, e := range v.Events {
		var params []string
		for _, a := range e.Type.Func.Params {
			params = append(params, a.Name+" "+a.Type.Go)
		}
		g.printf("// %s sends the %s event.\n", e.Name, e.Name)
		g.printf("func (e %sEvents) %s(%s) {\n\tw := native.NewWriter()\n", n, e.Name, strings.Join(params, ", "))
		for _, a := range e.Type.Func.Params {
			g.printf("\t%s\n", g.enc(a.Type, "w", a.Name))
		}
		g.printf("\te.Context.Emit(%q, map[string]any{\"v\": w.Take()})\n}\n\n", e.Name)
	}
	g.printf("// implement%s makes Go's implementation the %s on this platform: call\n// it from an init function of a file built for it (Windows, Linux).\n", n, n)
	g.printf("func implement%s(make func(events %sEvents) %sNative) {\n", n, n, n)
	g.printf("\tnative.RegisterView(native.ViewKind(nativeModule, %q), func(ctx native.Context) native.View {\n", n)
	g.printf("\t\tv := make(%sEvents{ctx})\n\t\treturn native.GoView(v, func(name string, value []byte) {\n\t\t\tr := native.NewReader(value)\n\t\t\tswitch name {\n", n)
	for _, f := range v.Props {
		g.printf("\t\t\tcase %q:\n\t\t\t\tif a := %s; r.Err() == nil {\n\t\t\t\t\tv.Set%s(a)\n\t\t\t\t}\n", f.Name, g.dec(f.Type, "r"), f.Name)
	}
	g.printf("\t\t\t}\n\t\t})\n\t})\n}\n\n")
}
